model:
class Planet

class Earth extending Planet

class Mars extending Planet

class Spacecraft {
  cost:Real
  destination:Planet
}

class LowCostSCFleet {
  deployedSC:Set[Spacecraft]

  req forall sc : Spacecraft . sc isin deployedSC => sc.cost < 1E6
}

class FeasibleLowCostSCFleet {
  deployedSC:Set[Spacecraft]

  req deployedSC != Set{}

  req forall sc : Spacecraft . sc isin deployedSC => sc.destination is Earth
}
